		"sessionId":"ses-1",
		"messages":[
			{
				"id":"msg-u1","timestamp":"2026-01-01T00:00:00Z","type":"user",
				"content":"hello"
			},
			{
				"id":"msg-a1","timestamp":"2026-01-01T00:00:01Z","type":"gemini",
				"content":"Hi there!",
				"tokens":{"input":200,"output":75,"cached":0,"thoughts":10,"tool":0,"total":285}
